  <style>:root{--navy:#071d33;--navy2:#0d2f50;--blue:#155d91;--red:#c8102e;--sky:#91d7f4;--ink:#142234;--muted:#637184;--line:#dce4eb;--paper:#f5f8fb;--white:#fff;--green:#087f5b;--amber:#b35a00}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;font-size:16px;line-height:1.55}.site-header{height:82px;padding:0 clamp(22px,5vw,72px);display:flex;align-items:center;justify-content:space-between;background:var(--navy);color:#fff;border-bottom:1px solid rgba(255,255,255,.12);position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none}.brand-mark{display:grid;place-items:center;width:44px;height:44px;border-radius:10px;background:#fff;color:var(--red);font-weight:900;letter-spacing:-1px}.brand b,.brand small{display:block}.brand b{font-size:16px;letter-spacing:.04em}.brand small{font-size:11px;color:#b8cede;letter-spacing:.08em}.site-header nav{display:flex;align-items:center;gap:28px}.site-header nav a{color:#dceaf4;text-decoration:none;font-weight:650;font-size:14px}.site-header .nav-cta{padding:11px 16px;background:var(--red);color:#fff;border-radius:7px}main{max-width:1440px;margin:auto}.intro{display:grid;grid-template-columns:1.25fr .75fr;gap:48px;padding:58px clamp(22px,6vw,88px) 38px;background:linear-gradient(135deg,var(--navy),var(--navy2));color:#fff}.eyebrow,.section-label{display:block;font-size:12px;font-weight:850;letter-spacing:.14em;color:var(--red);margin-bottom:9px}.intro .eyebrow{color:var(--sky)}h1{font-size:clamp(36px,5vw,64px);line-height:1.02;letter-spacing:-.04em;margin:0;max-width:850px}.intro>p{align-self:end;color:#c5d8e6;font-size:18px;max-width:500px;margin:0 0 8px}.lab-shell{margin:0 clamp(18px,4vw,56px);transform:translateY(22px);box-shadow:0 22px 60px rgba(7,29,51,.16);border-radius:14px;overflow:hidden;background:#fff}.demo-tabs{display:grid;grid-template