background:#fff0db;color:var(--amber)}.empty-state{display:grid;place-items:center;min-height:330px;text-align:center;color:var(--muted)}.empty-state p{max-width:360px}.scan-lines{width:88px;height:70px;background:repeating-linear-gradient(to bottom,#cbd8e2 0 3px,transparent 3px 13px);opacity:.75}.hidden{display:none}.results{padding-top:20px}.summary{font-size:17px;margin:0 0 18px;color:#2c3a49}.metric-row{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px}.metric{padding:13px;background:#fff;border:1px solid var(--line);border-radius:7px}.metric strong,.metric span{display:block}.metric strong{font-size:20px;color:var(--navy)}.metric span{font-size:12px;color:var(--muted)}.finding-list{display:grid;gap:9px}.finding{display:grid;grid-template-columns:82px 1fr;gap:12px;padding:12px 14px;background:#fff;border-left:4px solid var(--blue);border-radius:5px;box-shadow:0 1px 0 var(--line)}.finding.high{border-color:var(--red)}.finding.medium{border-color:#e29b22}.finding .tag{font-size:11px;font-weight:900;letter-spacing:.07em;color:var(--muted)}.finding b{font-size:14px}.finding p{grid-column:2;margin:2px 0 0;color:var(--muted);font-size:13px}.proof-strip{margin:64px clamp(22px,6vw,88px) 44px;display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}.proof-strip article{background:#fff;padding:24px}.proof-strip strong,.proof-strip span{display:block}.proof-strip strong{color:var(--navy);margin-bottom:6px}.proof-strip span{font-size:14px;color:var(--muted)}.cta{margin:0 clamp(22px,6vw,88px) 28px;padding:40px 44px;border-radius:12px;background:var(--navy);color:#fff;display:flex;justify-content:space-between;gap:40px;align-items:center}.cta h2{font-size:clamp(28px,3vw,42px);line-height:1.12;margin:0 0 10px;letter-spacing:-.025em}.cta p{margin:0;color:#bed1df;max-width:780px}.cta a{flex:none;padding:15px 20px;border-radius:7px;background:var(--red);color:#fff;text-decoration:none;font-weight:850}.