.problem-picker{padding:44px clamp(22px,6vw,88px) 24px}.picker-heading{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:22px}.picker-heading h2{font-size:clamp(27px,3vw,40px);line-height:1.1;margin:0;color:var(--navy);max-width:720px}.problem-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.problem{position:relative;min-height:220px;padding:24px;text-align:left;border:1px solid var(--line);border-radius:11px;background:#fff;color:var(--ink);font:inherit;cursor:pointer;transition:.2s ease}.problem:hover,.problem.active{border-color:var(--blue);box-shadow:0 12px 30px rgba(8,42,71,.1);transform:translateY(-2px)}.problem.active{box-shadow:inset 0 4px 0 var(--red),0 12px 30px rgba(8,42,71,.1)}.problem-number{display:block;color:var(--red);font-size:12px;font-weight:900;letter-spacing:.12em;margin-bottom:24px}.problem strong,.problem small,.see-demo{display:block}.problem strong{font-size:19px;line-height:1.25;margin-bottom:10px}.problem small{font-size:14px;color:var(--muted);line-height:1.45}.see-demo{position:absolute;bottom:20px;color:var(--blue);font-size:13px;font-weight:850}.lab-shell{margin-top:22px;transform:none}.before-after{display:grid;grid-template-columns:1fr 1fr;margin:0 0 22px;border:1px solid var(--line);border-radius:7px;overflow:hidden}.before-after div{padding:12px}.before-after div+div{border-left:1px solid var(--line);background:#edf8f4}.before-after span,.before-after b{display:block}.before-after span{font-size:10px;font-weight:900;letter-spacing:.1em;color:var(--muted);margin-bottom:4px}.before-after b{font-size:13px;line-height:1.35}.possibility{margin:58px clamp(22px,6vw,88px) 24px;padding:42px;background:#fff;border:1px solid var(--line);display:grid;grid-template-columns:.8fr 1.2fr;gap:60px}.possibility h2{font-size:clamp(28px,3vw,42px);line-height:1.1;margin:0;color:var(--navy)}.possibility-copy p{font-size:18px;margin:0 0 20px}.possibility-copy ul{padding-left:20px;margin:0;color:var(--muted)}