.how-section{margin:64px clamp(22px,6vw,88px);scroll-margin-top:100px}.how-heading{max-width:870px;margin-bottom:30px}.how-heading h2{font-size:clamp(32px,4vw,52px);line-height:1.06;letter-spacing:-.035em;color:var(--navy);margin:0 0 15px}.how-heading p{font-size:18px;color:var(--muted);margin:0;max-width:800px}.how-flow{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;border:1px solid var(--line);background:var(--line);border-radius:12px 12px 0 0;overflow:hidden}.how-step{min-height:160px;padding:22px;border:0;background:#fff;text-align:left;font:inherit;color:var(--ink);cursor:pointer}.how-step span,.how-step b,.how-step small{display:block}.how-step span{width:30px;height:30px;display:grid;place-items:center;border-radius:50%;background:#e8eef3;color:var(--navy);font-size:12px;font-weight:900;margin-bottom:17px}.how-step b{font-size:16px;margin-bottom:7px}.how-step small{font-size:13px;line-height:1.4;color:var(--muted)}.how-step.active{background:var(--navy);color:#fff}.how-step.active span{background:var(--red);color:#fff}.how-step.active small{color:#bfd1df}.walkthrough{display:grid;grid-template-columns:1fr 1fr;background:#eaf0f5;border-radius:0 0 12px 12px;min-height:360px}.walkthrough-copy,.example-card{padding:42px}.walkthrough-label,.example-card>span{font-size:11px;letter-spacing:.12em;font-weight:900;color:var(--red)}.walkthrough h3{font-size:clamp(26px,3vw,38px);line-height:1.12;color:var(--navy);margin:12px 0}.walkthrough-copy>p{color:var(--muted);font-size:17px;margin:0 0 26px}.secondary-button{border:1px solid var(--navy);background:transparent;color:var(--navy);padding:12px 15px;border-radius:7px;font:inherit;font-weight:800;cursor:pointer}.example-card{margin:26px;background:#fff;border:1px solid var(--line);border-radius:9px;box-shadow:0 12px 30px rgba(7,29,51,.08)}.example-card>p{font-size:14px;color:var(--muted);border-top:1px solid var(--line);margin:20px 0 0;padding-top:17px}.input-stack{display:grid;gap:9px;margin-top:22px}.input-stack div{padding:14px;border:1px solid var(--line);border-radius:6px;font-weight:750;display:flex;justify-content:space-between}.input-stack b{font-size:12px;color:var(--muted)}.input-stack .positive{border-left:4px solid var(--green)}.input-stack .warning{border-left:4px solid #e29b22}.input-stack .critical{border-left:4px solid var(--red)}.build-path{margin-top:24px;padding:34px;background:var(--navy);color:#fff;display:grid;grid-template-columns:.65fr 1.35fr;gap:38px;border-radius:12px}.build-path h3{font-size:26px;line-height:1.2;margin:0}.build-path ol{counter-reset:path;display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:0;padding:0;list-style:none}.build-path li{position:relative;padding-left:42px}.build-path li:before{counter-increment:path;content:counter(path);position:absolute;left:0;top:0;width:28px;height:28px;display:grid;place-items:center;border-radius:50%;background:var(--red);font-size:12px;font-weight:900}.build-path b,.build-path span{display:block}.build-path span{color:#bcd0de;font-size:13px;margin-top:3px}@media(max-width:900px){.how-flow{grid-template-columns:1fr 1fr}.walkthrough{grid-template-columns:1fr}.build-path{grid-template-columns:1fr}}@media(max-width:560px){.how-flow{grid-template-columns:1fr}.walkthrough-copy,.example-card{padding:25px}.example-card{margin:0 18px 18px}.build-path ol{grid-template-columns:1fr}}

.interaction-prompt{display:flex;align-items:center;gap:9px;margin:0 0 10px;color:var(--blue);font-size:13px;font-weight:850;letter-spacing:.02em}.interaction-prompt span{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:var(--blue);color:#fff}.how-step{position:relative;padding-bottom:48px;transition:background .18s ease,color .18s ease,transform .18s ease,box-shadow .18s ease}.how-step em{position:absolute;left:22px;bottom:18px;color:var(--blue);font-size:10px;font-style:normal;font-weight:900;letter-spacing:.08em;opacity:.76;transition:transform .18s ease,opacity .18s ease}.how-step:hover,.how-step:focus-visible{background:#f0f7fb;box-shadow:inset 0 -4px 0 var(--blue);transform:translateY(-2px);outline:none}.how-step:hover em,.how-step:focus-visible em{opacity:1;transform:translateX(4px)}.how-step.active{box-shadow:inset 0 -4px 0 var(--red)}.how-step.active em{color:var(--sky);opacity:1}.walkthrough{position:relative}.walkthrough.is-changing{animation:walkthroughChange .28s ease}.walkthrough-controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.text-step-button{border:0;background:transparent;color:var(--muted);padding:12px 4px;font:inherit;font-size:14px;font-weight:800;cursor:pointer}.text-step-button:hover,.text-step-button:focus-visible{color:var(--blue);text-decoration:underline}.secondary-button:hover,.secondary-button:focus-visible{background:var(--navy);color:#fff;outline:none}.how-step.active:after{content:'NOW VIEWING';position:absolute;right:17px;top:19px;color:var(--sky);font-size:9px;font-weight:900;letter-spacing:.09em}@keyframes walkthroughChange{from{opacity:.55;transform:translateY(8px)}to{opacity:1;transform:none}}@media(max-width:560px){.interaction-prompt{align-items:flex-start}.how-step{min-height:145px}.walkthrough-controls{align-items:stretch;flex-direction:column-reverse}.text-step-button,.secondary-button{width:100%}}

.sample-result-header{display:flex;align-items:center;justify-content:space-between;gap:12px}.sample-result-header>span{font-size:11px;letter-spacing:.12em;font-weight:900;color:var(--red)}.sample-result-header small{padding:5px 8px;border-radius:20px;background:#edf2f6;color:var(--muted);font-size:9px;font-weight:900;letter-spacing:.08em}.example-card h4{margin:12px 0 4px;color:var(--navy);font-size:22px;line-height:1.2}@media(max-width:560px){.sample-result-header{align-items:flex-start;flex-direction:column}.example-card h4{font-size:19px}}

.conversation-launcher{position:fixed;right:24px;bottom:22px;z-index:20;display:flex;align-items:center;gap:12px;padding:13px 17px;border:0;border-radius:12px;background:var(--red);color:#fff;box-shadow:0 15px 38px rgba(7,29,51,.28);font:inherit;text-align:left;cursor:pointer}.conversation-launcher b,.conversation-launcher small{display:block}.conversation-launcher b{font-size:14px}.conversation-launcher small{color:#ffd9df;font-size:11px}.conversation-pulse{width:11px;height:11px;border-radius:50%;background:#fff;box-shadow:0 0 0 0 rgba(255,255,255,.65);animation:conversationPulse 2s infinite}.conversation-panel{position:fixed;right:24px;bottom:94px;z-index:25;width:min(410px,calc(100vw - 32px));max-height:min(680px,calc(100vh - 120px));display:grid;grid-template-rows:auto minmax(180px,1fr) auto auto;overflow:hidden;border:1px solid #cbd6df;border-radius:16px;background:#fff;box-shadow:0 24px 70px rgba(7,29,51,.32)}.conversation-panel.hidden{display:none}.conversation-panel header{display:flex;justify-content:space-between;align-items:flex-start;padding:20px;background:var(--navy);color:#fff}.conversation-panel header span,.conversation-panel header b,.conversation-panel header small{display:block}.conversation-panel header span{color:var(--sky);font-size:9px;font-weight:900;letter-spacing:.13em}.conversation-panel header b{font-size:18px}.conversation-panel header small{color:#bcd0de;font-size:10px}.conversation-panel header button{border:0;background:transparent;color:#fff;font-size:28px;line-height:1;cursor:pointer}.conversation-thread{padding:18px;overflow:auto;background:#f4f7fa;display:flex;flex-direction:column;gap:12px}.message{max-width:88%;padding:12px 14px;border-radius:12px}.message p{margin:2px 0 0;font-size:14px;line-height:1.45}.message small{font-size:9px;font-weight:900;letter-spacing:.1em}.guide-message{align-self:flex-start;background:#fff;border:1px solid var(--line);border-bottom-left-radius:3px}.guide-message small{color:var(--red)}.visitor-message{align-self:flex-end;background:var(--navy);color:#fff;border-bottom-right-radius:3px}.visitor-message small{color:var(--sky)}.conversation-choices{display:flex;flex-wrap:wrap;gap:7px;padding:12px 18px 4px;background:#fff}.conversation-choices button{padding:9px 11px;border:1px solid var(--blue);border-radius:20px;background:#fff;color:var(--blue);font:inherit;font-size:12px;font-weight:800;cursor:pointer}.conversation-choices button:hover,.conversation-choices button:focus-visible{background:var(--blue);color:#fff}.conversation-form{padding:11px 18px 18px;background:#fff}.conversation-form label{display:block;margin-bottom:5px;color:var(--muted);font-size:10px;font-weight:800}.conversation-form>div{display:flex;border:1px solid #bfcbd5;border-radius:8px;overflow:hidden}.conversation-form input{min-width:0;flex:1;padding:11px;border:0;font:inherit;font-size:13px;outline:none}.conversation-form button{border:0;background:var(--navy);color:#fff;padding:0 14px;font-weight:800;cursor:pointer}.chat-summary{border-left:4px solid var(--red)}.chat-summary b{display:block;color:var(--navy);margin-bottom:4px}.chat-link{display:inline-block;margin-top:9px;color:var(--blue);font-weight:850;text-decoration:none}.typing{color:var(--muted);font-size:12px;font-style:italic}@keyframes conversationPulse{70%{box-shadow:0 0 0 9px rgba(255,255,255,0)}100%{box-shadow:0 0 0 0 rgba(255,255,255,0)}}@media(max-width:560px){.conversation-launcher{right:16px;bottom:14px}.conversation-panel{right:16px;bottom:82px;max-height:calc(100vh - 100px)}}

.intro{align-items:center}.intro>div:first-child{max-width:900px}.hero-support{font-size:19px;color:#c5d8e6;max-width:760px;margin:22px 0 0}.hero-promise{align-self:center;padding:25px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.06);border-radius:10px}.hero-promise strong,.hero-promise span,.hero-promise a{display:block}.hero-promise strong{font-size:18px}.hero-promise span{color:#c5d8e6;margin:7px 0 20px}.hero-promise a{color:#fff;font-size:14px;font-weight:850;text-decoration:none}.opportunity-builder{margin:38px clamp(18px,4vw,56px) 18px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 18px 46px rgba(7,29,51,.12);overflow:hidden;scroll-margin-top:100px}.builder-top{display:flex;justify-content:space-between;align-items:end;padding:30px 34px;border-bottom:1px solid var(--line)}.builder-top h2{font-size:clamp(26px,3vw,38px);line-height:1.15;color:var(--navy);margin:0}.builder-progress{display:flex;gap:6px}.builder-progress span{width:42px;height:5px;border-radius:5px;background:#dae3ea}.builder-progress span.active{background:var(--red)}.builder-body{display:grid;grid-template-columns:1.35fr .65fr;min-height:360px}.builder-question{padding:36px}.question-number,.builder-guide>span,.recommendation-action>span{font-size:11px;letter-spacing:.12em;font-weight:900;color:var(--red)}.builder-question h3{font-size:26px;color:var(--navy);margin:9px 0 22px}.answer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.answer-grid button{min-height:160px;padding:22px;text-align:left;border:1px solid var(--line);background:#fff;border-radius:9px;font:inherit;cursor:pointer;transition:.18s ease}.answer-grid button:hover,.answer-grid button.selected{border-color:var(--blue);background:#f2f8fc;transform:translateY(-2px);box-shadow:0 10px 22px rgba(10,46,80,.08)}.answer-grid b,.answer-grid small{display:block}.answer-grid b{font-size:17px;color:var(--navy);margin-bottom:8px}.answer-grid small{font-size:13px;color:var(--muted);line-height:1.45}.builder-guide{padding:36px;background:#eaf0f5;border-left:1px solid var(--line)}.builder-guide h3{font-size:22px;line-height:1.25;color:var(--navy);margin:10px 0}.builder-guide p{font-size:14px;color:var(--muted)}.guide-proof{display:grid;grid-template-columns:auto 1fr;gap:3px 10px;margin-top:22px}.guide-proof b{color:var(--navy);font-size:13px}.guide-proof span{font-size:12px;color:var(--muted)}.guide-proof i{display:none}.recommendation{display:grid;grid-template-columns:1.25fr .75fr;background:#f4f8fb}.recommendation>div{padding:38px}.recommendation h3{font-size:clamp(28px,3vw,40px);line-height:1.12;color:var(--navy);margin:8px 0 12px}.recommendation p{color:var(--muted);font-size:17px}.recommended-outcomes{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.recommended-outcomes span{padding:8px 11px;border-radius:20px;background:#e0f1ea;color:#09694e;font-size:12px;font-weight:800}.recommendation-action{background:var(--navy);color:#fff}.recommendation-action ol{padding-left:20px;color:#c5d8e6;font-size:14px}.recommendation-action li{margin:8px 0}.recommendation-action button{width:100%;padding:13px 15px;border:0;border-radius:7px;background:var(--red);color:#fff;font:inherit;font-weight:850;cursor:pointer}.recommendation-action .text-button{margin-top:10px;background:transparent;color:#bcd0de}.builder-question.fade{animation:questionIn .25s ease}@keyframes questionIn{from{opacity:.15;transform:translateX(12px)}to{opacity:1;transform:none}}@media(max-width:900px){.builder-body,.recommendation{grid-template-columns:1fr}.builder-guide{border-left:0;border-top:1px solid var(--line)}.answer-grid{grid-template-columns:1fr}.answer-grid button{min-height:auto}.builder-top{align-items:start;gap:20px}}@media(max-width:560px){.builder-top,.builder-question,.builder-guide,.recommendation>div{padding:24px}.builder-progress span{width:24px}}
