<body>
  <header class="site-header">
    <a class="brand" href="/" aria-label="PE Tech Partners home"><span class="brand-mark">PE</span><span><b>PE TECH PARTNERS</b><small>AI APPLICATIONS FOR DEAL TEAMS</small></span></a>
    <nav aria-label="Primary navigation"><a href="#lab">Solutions Lab</a><a href="#how">How it works</a><a class="nav-cta" href="#contact">Build this for your firm</a></nav>
  </header>

  <main>
    <section class="intro" id="lab">
      <div><span class="eyebrow">START WITH THE BOTTLENECK</span><h1>What is slowing your team down?</h1><p class="hero-support">Choose one problem you recognize. See a practical way to reduce the manual work before you decide whether to take another step.</p></div>
      <div class="hero-promise"><strong>Bring us one frustrating workflow.</strong><span>We’ll show you what the work could look like when information is organized, exceptions are visible, and people stay in control.</span><a href="#opportunity">Show me a possible solution ↓</a></div>
    </section>

    <section class="opportunity-builder" id="opportunity" aria-labelledby="opportunity-title">
      <div class="builder-top"><div><span class="section-label">SOLVE ONE PROBLEM FIRST</span><h2 id="opportunity-title">Which work would you like to make easier?</h2></div><div class="builder-progress" aria-label="One quick choice"><span class="active"></span></div></div>
      <div class="builder-body">
        <div class="builder-question" id="builder-question">
          <span class="question-number">CHOOSE A FAMILIAR PROBLEM</span><h3>Where is your team losing time or visibility?</h3>
          <div class="answer-grid" data-question="bottleneck">
            <button data-value="intake"><b>Reading and organizing</b><small>Incoming material takes hours to turn into something useful.</small></button>
            <button data-value="evidence"><b>Finding what is missing</b><small>Important gaps hide across folders, email, and spreadsheets.</small></button>
            <button data-value="plan"><b>Turning findings into action</b><small>Ownership and next steps take too long to become clear.</small></button>
          </div>
        </div>
        <aside class="builder-guide"><span>NO FORM. NO SALES PITCH.</span><h3>See the idea before doing any work.</h3><p>One choice gives you a suggested application, the business result it could produce, and a working fictional example you can explore.</p><div class="guide-proof"><b>Choose</b><span>the problem</span><i>→</i><b>See</b><span>a possible solution</span><i>→</i><b>Explore</b><span>only if it is useful</span></div></aside>
      </div>
      <div class="recommendation hidden" id="recommendation" aria-live="polite"><div><span class="section-label">ONE POSSIBLE SOLUTION</span><h3 id="recommendation-title"></h3><p id="recommendation-copy"></p><div class="recommended-outcomes" id="recommended-outcomes"></div></div><div class="recommendation-action"><span>You are in control</span><ol><li>See the fictional working example</li><li>Decide whether the idea is relevant</li><li>Leave without entering any information</li></ol><button id="launch-recommendation">Show me the working example <span>→</span></button><button id="restart-builder" class="text-button">Choose a different problem</button></div></div>
    </section>

    <section class="problem-picker" aria-labelledby="problem-title">
      <div class="picker-heading"><span class="section-label">OR EXPLORE THE LAB</span><h2 id="problem-title">Choose a business problem you recognize.</h2></div>
      <div class="problem-grid">
        <button class="problem active" data-target="intake"><span class="problem-number">01</span><strong>We spend hours reading new deal documents</strong><small>See how an application can organize the important facts and questions.</small><span class="see-demo">Show me →</span></button>
        <button class="problem" data-target="evidence"><span class="problem-number">02</span><strong>We’re never sure what is missing from the file</strong><small>See how an application can check evidence and surface gaps before they become surprises.</small><span class="see-demo">Show me →</span></button>
        <button class="problem" data-target="plan"><span class="problem-number">03</span><strong>Our post-close plan lives in meetings and spreadsheets</strong><small>See how an application can turn findings into an accountable 90-day plan.</small><span class="see-demo">Show me →</span></button>
      </div>
    </section>

    <section class="lab-shell" aria-label="AI proof of concept demonstrations">
      <div class="demo-tabs" role="tablist" aria-label="Choose a demonstration">
        <button class="demo-tab active" role="tab" aria-selected="true" data-demo="intake"><span>01</span>Review a deal package</button>
        <button class="demo-tab" role="tab" aria-selected="false" data-demo="evidence"><span>02</span>Check what’s missing</button>
        <button class="demo-tab" role="tab" aria-selected="false" data-demo="plan"><span>03</span>Build the first 90 days</button>
      </div>

      <div class="demo-panel">
        <div class="workspace">
          <section class="control-card">
            <span class="section-label" id="control-kicker">SYNTHETIC CIM</span>
            <h2 id="demo-title">AI Deal Intake</h2>
            <p id="demo-description">Turn an incoming deal document into a structured first-pass review.</p>
            <div id="before-after" class="before-after"></div>
            <label for="scenario">Choose an example company</label>
            <select id="scenario"></select>
            <div id="scenario-facts" class="scenario-facts"></div>
            <button id="run-demo" class="primary-button"><span>Run analysis</span><span aria-hidden="true">→</span></button>
            <p class="privacy-note"><span aria-hidden="true">◆</span> Demonstration data only. Nothing is uploaded or retained.</p>
          </section>

          <section class="result-card" aria-live="polite">
            <div class="result-header"><div><span class="section-label">WHAT YOUR TEAM WOULD RECEIVE</span><h2 id="result-title">See the application at work</h2></div><span id="result-status" class="status ready">READY</span></div>
            <div id="empty-state" class="empty-state"><div class="scan-lines" aria-hidden="true"></div><p>Choose an example and press the button. The application will turn the source material into work your team can act on.</p></div>
            <div id="results" class="results hidden"></div>
          </section>
        </div>
      </div>
    </section>

    <section class="possibility" aria-labelledby="possibility-title">
      <div><span class="section-label">YOU ARE THE EXPERT IN YOUR BUSINESS</span><h2 id="possibility-title">The application is built around your workflow.</h2></div>
      <div class="possibility-copy"><p>These examples show a pattern: information comes in, the application organizes it, applies your rules, and sends useful work to the people and systems that need it.</p><ul><li>Connect your CRM, email, data room, spreadsheets, or internal systems</li><li>Use your firm’s questions, approval steps, and reporting format</li><li>Keep a person in control of important decisions</li><li>Measure turnaround time, missing work, and operational savings</li></ul></div>
    </section>

    <section class="how-section" id="how" aria-labelledby="how-title">
      <div class="how-heading"><span class="section-label">HOW IT WORKS</span><h2 id="how-title">Your process stays familiar. The repetitive work changes.</h2><p>We do not drop a generic chatbot into your business. We learn how work moves today, build around the decisions your team already makes, and keep people in control where judgment matters.</p></div>
      <p class="interaction-prompt"><span aria-hidden="true">↘</span> Select any step to see what your team would experience</p>
      <div class="how-flow" role="tablist" aria-label="Application workflow">
        <button class="how-step active" data-step="1" role="tab" aria-selected="true"><span>1</span><b>Work comes in</b><small>Documents, emails, forms, spreadsheets, or CRM records</small><em>VIEW THIS STEP →</em></button>
        <button class="how-step" data-step="2" role="tab" aria-selected="false"><span>2</span><b>The application prepares it</b><small>Organizes information, applies rules, and identifies exceptions</small><em>VIEW THIS STEP →</em></button>
        <button class="how-step" data-step="3" role="tab" aria-selected="false"><span>3</span><b>Your team reviews</b><small>People approve decisions, correct context, and handle judgment calls</small><em>VIEW THIS STEP →</em></button>
        <button class="how-step" data-step="4" role="tab" aria-selected="false"><span>4</span><b>The work moves forward</b><small>Updates systems, creates reports, assigns work, or triggers follow-up</small><em>VIEW THIS STEP →</em></button>
      </div>
      <div class="walkthrough">
        <div class="walkthrough-copy"><span class="walkthrough-label" id="walkthrough-label">STEP 1 · INPUT</span><h3 id="walkthrough-title">Start with work your team already receives.</h3><p id="walkthrough-text">The application can begin when a CIM arrives, a diligence file changes, a prospect completes a form, or a portfolio company submits an update.</p><div class="walkthrough-controls"><button id="previous-step" class="text-step-button" aria-label="View previous step">← Previous</button><button id="next-step" class="secondary-button">Next: prepare the work <span aria-hidden="true">→</span></button></div></div>
        <div class="example-card"><div class="sample-result-header"><span id="sample-result-label">SAMPLE INPUT · NEW DEAL INTAKE</span><small>FICTIONAL EXAMPLE</small></div><h4 id="sample-result-title">Source package received</h4><div id="walkthrough-visual" class="input-stack"><div>CIM.pdf <b>42 pages</b></div><div>Seller email <b>3 attachments</b></div><div>CRM opportunity <b>New</b></div></div><p id="walkthrough-outcome">Instead of asking someone to assemble the starting file, the application gathers the agreed source material.</p></div>
      </div>
      <div class="build-path"><div><span class="section-label">FROM IDEA TO A WORKING APPLICATION</span><h3>A focused path, with proof at every stage.</h3></div><ol><li><b>Discovery</b><span>Choose one costly workflow and define what “better” means.</span></li><li><b>Proof of concept</b><span>Build a small working version using safe sample data.</span></li><li><b>Pilot</b><span>Test with real users, permissions, and a controlled set of work.</span></li><li><b>Production</b><span>Connect systems, monitor results, and improve the workflow.</span></li></ol></div>
    </section>

    <section class="proof-strip">
      <article><strong>Structured</strong><span>Consistent outputs your team can review and reuse</span></article>
      <article><strong>Traceable</strong><span>Findings tied back to the source evidence</span></article>
      <article><strong>Connected</strong><span>Designed to fit CRMs, data rooms, and reporting systems</span></article>
      <article><strong>Secure</strong><span>Built around permissions, retention, and human review</span></article>
    </section>

    <section class="cta" id="contact">
      <div><span class="eyebrow">FROM PROOF OF CONCEPT TO PRODUCTION</span><h2>What would you remove from your team’s manual workload?</h2><p>PE Tech Partners designs and develops practical AI applications and automations for M&amp;A firms and technical businesses.</p></div>
      <a href="https://petechpartners.com/schedule.php">Build this for your firm <span aria-hidden="true">→</span></a>
    </section>

    <aside class="disclaimer"><strong>Demonstration notice</strong><p>These proof-of-concepts use fictional data and simplified decision logic. Results are illustrative and are not legal, financial, investment, cybersecurity, or compliance advice.</p></aside>
  </main>

  <footer><span>PE Tech Partners</span><span>Technology that moves deals forward.</span><span>© 2026</span></footer>
  <button class="conversation-launcher" id="conversation-launcher" aria-expanded="false" aria-controls="conversation-panel"><span class="conversation-pulse" aria-hidden="true"></span><span><b>Show me what AI could remove</b><small>See a sample result instantly</small></span></button>
  <aside class="conversation-panel hidden" id="conversation-panel" aria-label="Workflow conversation">
    <header><div><span>PE TECH PARTNERS</span><b>Workflow guide</b><small>Interactive prototype · no information is sent</small></div><button id="conversation-close" aria-label="Close conversation">×</button></header>
    <div class="conversation-thread" id="conversation-thread" aria-live="polite">
      <div class="message guide-message"><small>WORKFLOW GUIDE</small><p>Choose one familiar problem. I’ll show you a useful fictional result immediately—no form and no setup.</p></div>
    </div>
    <div class="conversation-choices" id="conversation-choices"></div>
    <form class="conversation-form" id="conversation-form"><label for="conversation-input">Or describe the problem in your own words</label><div><input id="conversation-input" placeholder="For example: We chase missing documents…" autocomplete="off"><button type="submit">Send</button></div></form>
  </aside>
  <script>const demos={
  intake:{kicker:'READING AND ORGANIZING A NEW OPPORTUNITY',title:'Review a deal package',description:'Instead of starting with a blank page, your team receives an organized first pass of the material.',before:['TODAY','An analyst reads, copies, checks, and builds questions by hand.'],after:['WITH THE APPLICATION','The first review is ready in minutes for a person to verify.'],button:'Show me the first-pass review',scenarios:[
    {name:'Northstar Precision Components',facts:[['Industry','Aerospace manufacturing'],['Revenue','$48.2M'],['EBITDA','$7.6M'],['Document','24-page CIM']],summary:'Northstar is a profitable, founder-led precision manufacturer with concentrated aerospace exposure and a credible capacity-expansion thesis.',metrics:[['16','facts extracted'],['4','risks flagged'],['6','follow-up questions']],findings:[['HIGH','Customer concentration','Top two customers represent 58% of revenue; renewal evidence is not included.'],['MEDIUM','Capex dependency','Growth plan assumes a new five-axis machining line without an executed purchase agreement.'],['MEDIUM','Key-person risk','Founder remains the primary technical estimator and owns three strategic relationships.'],['INFO','Quality signal','AS9100 certification and three-year on-time delivery trend are documented.']]},
    {name:'Alder Health Systems',facts:[['Industry','Healthcare software'],['ARR','$11.4M'],['Retention','108% NRR'],['Document','18-page teaser']],summary:'Alder presents a recurring-revenue healthcare workflow platform with strong retention but incomplete security and implementation-cost detail.',metrics:[['19','facts extracted'],['3','risks flagged'],['8','follow-up questions']],findings:[['HIGH','Security evidence','SOC 2 is referenced, but the report period and exceptions are not supplied.'],['MEDIUM','Services margin','Implementation labor is bundled into subscription economics.'],['MEDIUM','Pipeline quality','Forecast includes unsigned expansion opportunities.'],['INFO','Retention','Net revenue retention is reported at 108% across the last twelve months.']]}
  ]},
  evidence:{kicker:'CHECKING WHETHER THE FILE SUPPORTS THE STORY',title:'Check what’s missing',description:'Give reviewers one place to see what is present, what conflicts, and what still needs an answer.',before:['TODAY','People chase documents across folders, email, and spreadsheets.'],after:['WITH THE APPLICATION','The open questions and missing evidence are visible immediately.'],button:'Show me the evidence review',scenarios:[
    {name:'Atlas Growth SPV III',facts:[['Structure','Delaware SPV'],['Investors','14 subscribers'],['Target','Private software company'],['Documents','11 files']],summary:'The investor-to-SPV records are substantially complete, but the evidence connecting the SPV to the underlying shares is incomplete.',metrics:[['11','files reviewed'],['72%','evidence coverage'],['3','critical gaps']],findings:[['HIGH','Share ownership','No countersigned purchase agreement connects the SPV to the underlying shares.'],['HIGH','Cap table mismatch','SPV name differs between the operating agreement and issuer cap table.'],['HIGH','Funds trail','Wire confirmation identifies an affiliate rather than the SPV.'],['INFO','Investor records','All subscription agreements and accreditation records are present.']]},
    {name:'Beacon Industrial Add-on',facts:[['Transaction','Add-on acquisition'],['Jurisdictions','NY and NJ'],['Systems','7 core platforms'],['Documents','23 files']],summary:'Corporate evidence is complete, while technology ownership and access documentation require remediation before close.',metrics:[['23','files reviewed'],['83%','evidence coverage'],['4','open items']],findings:[['HIGH','Admin ownership','Two production systems use former-employee administrator accounts.'],['MEDIUM','Software rights','ERP support contract requires consent for assignment.'],['MEDIUM','Backup evidence','Restore testing is asserted but no test result is supplied.'],['INFO','Corporate file','Executed purchase and board-approval records are complete.']]}
  ]},
  plan:{kicker:'TURNING FINDINGS INTO OWNED ACTIONS',title:'Build the first 90 days',description:'Convert what you learned during the deal into a sequenced plan with priorities and decision points.',before:['TODAY','Findings sit in reports while owners and deadlines are negotiated.'],after:['WITH THE APPLICATION','A draft roadmap gives the team a shared starting point on day one.'],button:'Show me the 90-day roadmap',scenarios:[
    {name:'Multi-site Services Platform',facts:[['Locations','9 offices'],['Employees','420'],['IT teams','3 acquired teams'],['Priority','Identity consolidation']],summary:'The roadmap stabilizes access first, consolidates core systems second, and establishes an operating cadence before optimization.',metrics:[['14','workstreams'],['6','day-one actions'],['90','days mapped']],findings:[['HIGH','Days 0–30','Secure privileged accounts, preserve logs, validate backups, and establish an integration command center.'],['MEDIUM','Days 31–60','Consolidate identity, standardize endpoints, rationalize collaboration tools, and publish service ownership.'],['INFO','Days 61–90','Migrate reporting, automate onboarding, measure service levels, and approve the next modernization wave.'],['INFO','Executive cadence','Weekly risk review; biweekly value-capture report; day-90 steering decision.']]},
    {name:'Technical Product Carve-out',facts:[['Employees','115'],['Transition services','120 days'],['Applications','34 inventoried'],['Priority','Operational independence']],summary:'The plan prioritizes separation dependencies and continuity while delaying nonessential modernization until the carve-out is stable.',metrics:[['12','workstreams'],['8','TSA dependencies'],['90','days mapped']],findings:[['HIGH','Days 0–30','Confirm identity, hosting, licensing, support, and data-export obligations under the TSA.'],['MEDIUM','Days 31–60','Stand up independent core services and rehearse data migration and cutover.'],['INFO','Days 61–90','Exit priority TSA services, document ownership, and begin targeted workflow automation.'],['INFO','Decision gate','Do not retire seller access until reconciliation and rollback evidence are approved.']]}
  ]}
};

const tabs=[...document.querySelectorAll('.demo-tab')],problems=[...document.querySelectorAll('.problem')],scenario=document.querySelector('#scenario'),facts=document.querySelector('#scenario-facts'),run=document.querySelector('#run-demo'),results=document.querySelector('#results'),empty=document.querySelector('#empty-state'),status=document.querySelector('#result-status');let active='intake';
function renderScenario(){const item=demos[active].scenarios[scenario.selectedIndex];facts.innerHTML=item.facts.map(([a,b])=>`<div class="fact"><span>${a}</span><b>${b}</b></div>`).join('');results.classList.add('hidden');empty.classList.remove('hidden');status.className='status ready';status.textContent='READY';document.querySelector('#result-title').textContent='See the application at work'}
function renderDemo(){const demo=demos[active];document.querySelector('#control-kicker').textContent=demo.kicker;document.querySelector('#demo-title').textContent=demo.title;document.querySelector('#demo-description').textContent=demo.description;document.querySelector('#before-after').innerHTML=`<div><span>${demo.before[0]}</span><b>${demo.before[1]}</b></div><div><span>${demo.after[0]}</span><b>${demo.after[1]}</b></div>`;run.querySelector('span').textContent=demo.button;scenario.innerHTML=demo.scenarios.map(x=>`<option>${x.name}</option>`).join('');problems.forEach(x=>x.classList.toggle('active',x.dataset.target===active));renderScenario()}
function selectDemo(key,scroll=false){active=key;tabs.forEach(x=>{const on=x.dataset.demo===active;x.classList.toggle('active',on);x.setAttribute('aria-selected',on)});renderDemo();if(scroll)document.querySelector('.lab-shell').scrollIntoView({behavior:'smooth',block:'start'})}
tabs.forEach(tab=>tab.addEventListener('click',()=>selectDemo(tab.dataset.demo)));problems.forEach(problem=>problem.addEventListener('click',()=>selectDemo(problem.dataset.target,true)));scenario.addEventListener('change',renderScenario);
run.addEventListener('click',()=>{run.disabled=true;status.className='status running';status.textContent='ANALYZING';document.querySelector('#result-title').textContent='Reviewing sample data';empty.classList.remove('hidden');results.classList.add('hidden');setTimeout(()=>{const item=demos[active].scenarios[scenario.selectedIndex];document.querySelector('#result-title').textContent='Analysis complete';status.className='status complete';status.textContent='COMPLETE';empty.classList.add('hidden');results.innerHTML=`<p class="summary">${item.summary}</p><div class="metric-row">${item.metrics.map(([a,b])=>`<div class="metric"><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="finding-list">${item.findings.map(([level,title,text])=>`<article class="finding ${level.toLowerCase()}"><span class="tag">${level}</span><b>${title}</b><p>${text}</p></article>`).join('')}</div>`;results.classList.remove('hidden');run.disabled=false},850)});
renderDemo();

const howSteps={
  1:{label:'STEP 1 · INPUT',sampleLabel:'SAMPLE INPUT · NEW DEAL INTAKE',sampleTitle:'Source package received',title:'Start with work your team already receives.',text:'The application can begin when a CIM arrives, a diligence file changes, a prospect completes a form, or a portfolio company submits an update.',button:'Next: prepare the work',visual:[['CIM.pdf','42 pages',''],['Seller email','3 attachments',''],['CRM opportunity','New','']],outcome:'Instead of asking someone to assemble the starting file, the application gathers the agreed source material.'},
  2:{label:'STEP 2 · PREPARATION',sampleLabel:'SAMPLE RESULT · AUTOMATED FIRST PASS',sampleTitle:'Deal review prepared in 2 minutes',title:'The application handles the repeatable first pass.',text:'It can read, sort, compare, calculate, and apply your checklist. It does not make the final business decision; it prepares the work so your people can focus on what deserves attention.',button:'Next: human review',visual:[['Key facts extracted','16 complete','positive'],['Customer concentration','42% top five','warning'],['EBITDA figures','2 values conflict','critical'],['Follow-up questions','6 drafted','positive']],outcome:'Sample result: a structured review with traceable facts, visible exceptions, and six questions ready for an analyst.'},
  3:{label:'STEP 3 · HUMAN REVIEW',sampleLabel:'SAMPLE RESULT · REVIEW DECISIONS',sampleTitle:'Exceptions routed to the right owners',title:'Your people remain responsible for judgment.',text:'The right person reviews high-impact findings, corrects context, approves actions, and decides what moves forward. The application makes that review faster and more consistent.',button:'Next: move the work forward',visual:[['Financial profile','Approved by analyst','positive'],['Contract language','Assigned to counsel','warning'],['Customer risk','Escalated to IC','critical'],['Review record','Time and owner saved','positive']],outcome:'Sample result: routine findings are approved while legal language and customer concentration remain visibly assigned for judgment.'},
  4:{label:'STEP 4 · ACTION',sampleLabel:'SAMPLE RESULT · COMPLETED WORK',sampleTitle:'Approved actions moved into the business',title:'Approved work goes where the business needs it.',text:'The application can update the CRM, create a diligence request, assign an owner, prepare a report, or notify the team—without another round of copying and reformatting.',button:'Start again',visual:[['CRM opportunity','Updated','positive'],['Diligence request','6 items created','positive'],['IC summary','Draft ready','positive'],['Next review','Owner notified','positive']],outcome:'Sample result: the CRM is current, six requests are open, and the investment committee receives a consistent draft summary.'}
};
const howButtons=[...document.querySelectorAll('.how-step')],nextStep=document.querySelector('#next-step'),previousStep=document.querySelector('#previous-step'),walkthrough=document.querySelector('.walkthrough');let currentHow=1;
function renderHow(step){currentHow=Number(step);const item=howSteps[currentHow];howButtons.forEach(button=>{const on=Number(button.dataset.step)===currentHow;button.classList.toggle('active',on);button.setAttribute('aria-selected',on)});document.querySelector('#walkthrough-label').textContent=item.label;document.querySelector('#walkthrough-title').textContent=item.title;document.querySelector('#walkthrough-text').textContent=item.text;document.querySelector('#sample-result-label').textContent=item.sampleLabel;document.querySelector('#sample-result-title').textContent=item.sampleTitle;nextStep.firstChild.textContent=item.button+' ';previousStep.textContent=currentHow===1?'← View step 4':'← Previous step';document.querySelector('#walkthrough-visual').innerHTML=item.visual.map(([left,right,state])=>`<div class="${state}">${left}<b>${right}</b></div>`).join('');document.querySelector('#walkthrough-outcome').textContent=item.outcome;walkthrough.classList.remove('is-changing');void walkthrough.offsetWidth;walkthrough.classList.add('is-changing')}
howButtons.forEach(button=>button.addEventListener('click',()=>renderHow(button.dataset.step)));nextStep.addEventListener('click',()=>renderHow(currentHow===4?1:currentHow+1));previousStep.addEventListener('click',()=>renderHow(currentHow===1?4:currentHow-1));

const builderQuestions=[
  {key:'bottleneck',label:'CHOOSE A FAMILIAR PROBLEM',title:'Where is your team losing time or visibility?',answers:[['intake','Reading and organizing','Incoming material takes hours to turn into something useful.'],['evidence','Finding what is missing','Important gaps hide across folders, email, and spreadsheets.'],['plan','Turning findings into action','Ownership and next steps take too long to become clear.']]}
];
const builder={step:0,answers:{}},builderQuestion=document.querySelector('#builder-question'),progress=[...document.querySelectorAll('.builder-progress span')],recommendation=document.querySelector('#recommendation');
const recommendations={intake:{title:'A deal and document intake application',copy:'A practical first build could collect incoming material, organize the facts your team cares about, surface questions, and prepare a consistent first-pass review.',outcomes:['Shorter first review','Consistent questions','Less copying and reformatting'],demo:'intake'},evidence:{title:'An evidence and exception tracking application',copy:'A practical first build could compare the file to your checklist, show what is present, flag conflicting records, and keep unanswered questions visible.',outcomes:['Visible evidence gaps','Fewer missed items','Clear review ownership'],demo:'evidence'},plan:{title:'An execution and integration planning application',copy:'A practical first build could turn findings into sequenced actions, assign ownership, track decisions, and keep leadership informed.',outcomes:['Faster mobilization','Clear accountability','Repeatable reporting'],demo:'plan'}};
function drawBuilder(){const q=builderQuestions[builder.step];progress.forEach((x,i)=>x.classList.toggle('active',i<=builder.step));builderQuestion.classList.remove('fade');void builderQuestion.offsetWidth;builderQuestion.classList.add('fade');builderQuestion.innerHTML=`<span class="question-number">${q.label}</span><h3>${q.title}</h3><div class="answer-grid" data-question="${q.key}">${q.answers.map(([value,title,copy])=>`<button data-value="${value}"><b>${title}</b><small>${copy}</small></button>`).join('')}</div>`;builderQuestion.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>answerBuilder(q.key,button.dataset.value)))}
function answerBuilder(key,value){builder.answers[key]=value;showRecommendation()}
function showRecommendation(){const rec=recommendations[builder.answers.bottleneck]||recommendations.intake;document.querySelector('.builder-body').classList.add('hidden');document.querySelector('#recommendation-title').textContent=rec.title;document.querySelector('#recommendation-copy').textContent=rec.copy;document.querySelector('#recommended-outcomes').innerHTML=rec.outcomes.map(x=>`<span>${x}</span>`).join('');recommendation.dataset.demo=rec.demo;recommendation.classList.remove('hidden');progress.forEach(x=>x.classList.add('active'))}
document.querySelector('#launch-recommendation').addEventListener('click',()=>selectDemo(recommendation.dataset.demo,true));document.querySelector('#restart-builder').addEventListener('click',()=>{builder.step=0;builder.answers={};recommendation.classList.add('hidden');document.querySelector('.builder-body').classList.remove('hidden');drawBuilder()});
drawBuilder();

const chatLauncher=document.querySelector('#conversation-launcher'),chatPanel=document.querySelector('#conversation-panel'),chatClose=document.querySelector('#conversation-close'),chatThread=document.querySelector('#conversation-thread'),chatChoices=document.querySelector('#conversation-choices'),chatForm=document.querySelector('#conversation-form'),chatInput=document.querySelector('#conversation-input');
const chatState={stage:'problem',answers:{}};
const chatPrompts={problem:{text:'Choose another problem to see a different result.',options:[['Review a deal faster','intake'],['Find what is missing','evidence'],['Turn findings into action','plan']]},goal:{text:'If we adapted this to your workflow, what should improve first?',options:[['Faster turnaround','speed'],['Fewer surprises','confidence'],['Clearer ownership','execution']]}};
const instantSamples={intake:{title:'Sample: first-pass deal review',result:'In two minutes, 16 key facts are organized, two conflicting EBITDA figures are flagged, and six follow-up questions are drafted for an analyst.',demo:'intake'},evidence:{title:'Sample: missing-evidence report',result:'The checklist shows 27 items received, four missing, two records in conflict, and the owner responsible for each open question.',demo:'evidence'},plan:{title:'Sample: accountable 90-day plan',result:'Twelve workstreams are sequenced, eight transition-service dependencies are visible, and every first-30-day action has an owner and decision date.',demo:'plan'}};
function addChatMessage(text,who='guide',extra=''){const message=document.createElement('div'),label=document.createElement('small'),body=document.createElement('p');message.className=`message ${who==='visitor'?'visitor-message':'guide-message'} ${extra}`;label.textContent=who==='visitor'?'YOU':'WORKFLOW GUIDE';if(who==='visitor')body.textContent=text;else body.innerHTML=text;message.append(label,body);chatThread.appendChild(message);chatThread.scrollTop=chatThread.scrollHeight}
function setChatChoices(options){chatChoices.innerHTML=options.map(([label,value])=>`<button data-chat-value="${value}">${label}</button>`).join('');chatChoices.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>answerChat(button.textContent,button.dataset.chatValue)))}
function askChat(stage){chatState.stage=stage;const prompt=chatPrompts[stage];addChatMessage(prompt.text);setChatChoices(prompt.options)}
function bindChatSampleLinks(){chatThread.querySelectorAll('[data-chat-demo]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();selectDemo(link.dataset.chatDemo,true);chatPanel.classList.add('hidden');chatLauncher.setAttribute('aria-expanded','false')}))}
function showInstantSample(key){const sample=instantSamples[key]||instantSamples.intake;chatState.stage='sample';chatState.answers.problem=key;addChatMessage(`<b>${sample.title}</b>${sample.result}<br><a class="chat-link" href="#lab" data-chat-demo="${sample.demo}">Open the working sample →</a>`,'guide','chat-summary');setChatChoices([['Make it fit my workflow','personalize'],['Show another result','restart'],['Talk with our team','contact']]);bindChatSampleLinks()}
function finishPersonalization(value){const goal={speed:'shorten the time from source material to a review-ready result',confidence:'surface missing, conflicting, and high-risk items before they become surprises',execution:'turn approved findings into owned actions and system updates'}[value];addChatMessage(`<b>A sensible first success measure</b>Build the smallest version around your existing inputs and measure whether it can ${goal}. Your team would verify every important decision before anything moves forward.<br><a class="chat-link" href="#lab" data-chat-demo="${chatState.answers.problem}">See the closest working sample →</a>`,'guide','chat-summary');chatState.stage='complete';setChatChoices([['Explore another result','restart'],['Talk with our team','contact']]);bindChatSampleLinks()}
function answerChat(label,value){addChatMessage(label,'visitor');if(value==='restart'){chatState.answers={};askChat('problem');return}if(value==='contact'){location.href='https://petechpartners.com/schedule.php';return}if(value==='personalize'){askChat('goal');return}if(chatState.stage==='goal'){finishPersonalization(value);return}showInstantSample(value)}
chatLauncher.addEventListener('click',()=>{const opening=chatPanel.classList.contains('hidden');chatPanel.classList.toggle('hidden');chatLauncher.setAttribute('aria-expanded',opening);if(opening)chatChoices.querySelector('button')?.focus()});chatClose.addEventListener('click',()=>{chatPanel.classList.add('hidden');chatLauncher.setAttribute('aria-expanded','false');chatLauncher.focus()});
setChatChoices(chatPrompts.problem.options);
chatForm.addEventListener('submit',event=>{event.preventDefault();const text=chatInput.value.trim();if(!text)return;addChatMessage(text,'visitor');chatInput.value='';const lower=text.toLowerCase(),key=/missing|chase|gap|checklist|evidence/.test(lower)?'evidence':/plan|owner|task|action|implement|integration/.test(lower)?'plan':'intake';showInstantSample(key)});
</script>
</body>
</html>
